using System;
using System.IO;
using System.Linq;
public static class ChooserSavedAudit {
 public static ulong Hash(byte[] bytes) { unchecked { ulong h=14695981039346656037UL; foreach(byte b in bytes){h^=b;h*=1099511628211UL;} return h; } }
 public static byte[] Payload(string path) { var all=File.ReadAllBytes(path); using(var r=new BinaryReader(new MemoryStream(all))) {if(r.ReadUInt64()!=0x31504B434C524443UL)throw new Exception("wrapper magic:"+path);var n=r.ReadUInt64();var h=r.ReadUInt64();if(n!=(ulong)all.Length-24)throw new Exception("length:"+path);var bytes=r.ReadBytes((int)n);if(Hash(bytes)!=h)throw new Exception("checksum:"+path);return bytes;} }
 static float[] Floats(BinaryReader r) { var n=r.ReadUInt64();if(n>100000)throw new Exception("array bound");var x=new float[(int)n];for(int i=0;i<x.Length;i++){x[i]=r.ReadSingle();if(float.IsNaN(x[i])||float.IsInfinity(x[i]))throw new Exception("nonfinite float");}return x; }
 public sealed class Session { public string task; public int laneSize,countSize,update,actorSteps,criticSteps;public int[] config;public float[] constants,actor,critic,actorM,actorV,criticM,criticV;public uint steering,feedback,horizon;public ulong gait,offset,starts,worlds,counters,attempted,accepted,warmupAttempted,warmupAccepted;public uint keep,left,right,startsCount,clearance,cue,posture,bankLeft,bankRight;public ulong hash;public uint minimumEpisode=uint.MaxValue,maximumEpisode=0; }
 static int Adam(BinaryReader r,out float[] m,out float[] v){for(int i=0;i<5;i++){var x=r.ReadSingle();if(float.IsNaN(x)||float.IsInfinity(x))throw new Exception("Adam config");}var age=r.ReadInt32();m=Floats(r);v=Floats(r);if(age<0||m.Length!=v.Length||v.Any(x=>x<0))throw new Exception("Adam values");return age;}
 public static Session ReadSession(string path){var bytes=Payload(path);var s=new Session();s.hash=Hash(bytes);using(var r=new BinaryReader(new MemoryStream(bytes))){
  if(r.ReadUInt32()!=0x53435446||r.ReadUInt32()!=2)throw new Exception("session schema");var n=r.ReadUInt64();s.task=System.Text.Encoding.UTF8.GetString(r.ReadBytes((int)n));s.laneSize=(int)r.ReadUInt32();s.countSize=(int)r.ReadUInt32();s.config=new int[5];for(int i=0;i<5;i++)s.config[i]=r.ReadInt32();if(r.ReadUInt32()!=20261124)throw new Exception("seed");s.steering=r.ReadUInt32();s.feedback=r.ReadUInt32();s.horizon=r.ReadUInt32();if(s.steering!=1||s.feedback!=1||s.horizon!=1)throw new Exception("mode identity");s.gait=r.ReadUInt64();s.offset=r.ReadUInt64();s.starts=r.ReadUInt64();s.constants=new float[8];for(int i=0;i<8;i++)s.constants[i]=r.ReadSingle();r.ReadBytes(48);s.update=r.ReadInt32();s.actorSteps=r.ReadInt32();s.criticSteps=r.ReadInt32();s.actor=Floats(r);s.critic=Floats(r);var a=Adam(r,out s.actorM,out s.actorV);var c=Adam(r,out s.criticM,out s.criticV);if(a!=s.actorSteps||c!=s.criticSteps)throw new Exception("Adam age");s.worlds=r.ReadUInt64();
  var lanes=r.ReadBytes(checked((int)s.worlds*s.laneSize));
  for(int i=0;i<(int)s.worlds;i++){int p=i*s.laneSize;if(s.update>0&&(BitConverter.ToUInt32(lanes,p)!=1||BitConverter.ToUInt32(lanes,p+4)!=1||BitConverter.ToUInt32(lanes,p+8)!=1))throw new Exception("world mode");uint episode=BitConverter.ToUInt32(lanes,p+s.laneSize-8);if(episode<s.minimumEpisode)s.minimumEpisode=episode;if(episode>s.maximumEpisode)s.maximumEpisode=episode;if(s.update>0&&(episode==0||episode>(uint)(s.update*8+1)))throw new Exception("episode RNG position");if(lanes[p+s.laneSize-4]>1)throw new Exception("needs_start bool");}
  s.counters=r.ReadUInt64();if(s.countSize!=72)throw new Exception("unknown counts layout");
  for(ulong i=0;i<s.counters;i++){s.attempted+=r.ReadUInt64();s.accepted+=r.ReadUInt64();s.warmupAttempted+=r.ReadUInt64();s.warmupAccepted+=r.ReadUInt64();s.keep+=r.ReadUInt32();s.left+=r.ReadUInt32();s.right+=r.ReadUInt32();s.clearance+=r.ReadUInt32();s.cue+=r.ReadUInt32();s.posture+=r.ReadUInt32();s.startsCount+=r.ReadUInt32();s.bankLeft+=r.ReadUInt32();s.bankRight+=r.ReadUInt32();r.ReadUInt32();}
  if(r.BaseStream.Position!=r.BaseStream.Length)throw new Exception("trailing data");}return s; }
 public static float[] ReadActor(string path) {using(var r=new BinaryReader(new MemoryStream(Payload(path)))){if(r.ReadUInt32()!=0x48435446||r.ReadUInt32()!=1||r.ReadUInt32()!=32||r.ReadUInt32()!=3)throw new Exception("actor schema");return Floats(r);}}
 public static bool Equal(byte[] a,byte[] b){return a.SequenceEqual(b);}
}
